use super::*;
use bsc_incident::{Evidence, Incident, Kind, Severity, State};
use std::cell::RefCell;

fn incident(kind: Kind, sev: Severity, count: u64, summary: &str) -> Incident {
    Incident {
        id: 7,
        kind,
        key: "k".into(),
        severity: sev,
        source: "garage".into(),
        first_seen_ms: 1_000,
        last_seen_ms: 2_000,
        count,
        state: State::Open,
        evidence: Evidence::line(summary),
        notified: true,
    }
}

/// Records what it was asked to send, so the mapping is asserted without a network.
struct Recorder {
    sent: RefCell<Vec<(String, NtfyMessage)>>,
}
impl PushTransport for Recorder {
    fn send(&self, base_url: &str, msg: &NtfyMessage) -> Result<(), String> {
        self.sent.borrow_mut().push((base_url.to_string(), msg.clone()));
        Ok(())
    }
}

#[test]
fn severity_maps_to_ntfy_priority_across_the_whole_range() {
    assert_eq!(priority_for(Severity::Info), 1);
    assert_eq!(priority_for(Severity::Low), 2);
    assert_eq!(priority_for(Severity::Medium), 3);
    assert_eq!(priority_for(Severity::High), 4);
    // Critical is 5 — the one that breaks through Do-Not-Disturb.
    assert_eq!(priority_for(Severity::Critical), 5);
}

#[test]
fn every_kind_has_a_face_and_a_label() {
    for kind in [
        Kind::DeauthFlood,
        Kind::Jamming,
        Kind::ScanDetected,
        Kind::RogueDhcp,
        Kind::LeaseTheft,
        Kind::NewDevice,
        Kind::Other,
    ] {
        assert!(!tags_for(kind).is_empty(), "a notification must never be faceless: {kind:?}");
        assert!(!label_for(kind).is_empty(), "{kind:?}");
    }
}

#[test]
fn a_deauth_flood_becomes_a_max_priority_message_that_keeps_the_evidence() {
    let inc = incident(
        Kind::DeauthFlood,
        Severity::Critical,
        1,
        "RF ATTACK on 2437 MHz — strongest -31 dBm",
    );
    let m = ntfy_message(&inc, "home-alerts");
    assert_eq!(m.topic, "home-alerts");
    assert_eq!(m.priority, 5, "a critical attack is max priority");
    assert!(m.title.contains("CRITICAL") && m.title.contains("Deauth flood"), "{}", m.title);
    // the body must still carry the un-forgeable evidence the detector produced
    assert!(m.body.contains("2437 MHz"), "{}", m.body);
    assert!(m.body.contains("-31 dBm"), "{}", m.body);
    assert!(m.body.contains("garage"), "the sensor that heard it: {}", m.body);
    assert!(!m.tags.is_empty());
}

#[test]
fn a_coalesced_burst_says_how_many_times() {
    let inc = incident(Kind::ScanDetected, Severity::High, 60, "SSDP scan from 10.99.8.105");
    let m = ntfy_message(&inc, "t");
    assert!(m.body.contains("60×"), "a burst reads as a burst: {}", m.body);
    assert_eq!(m.priority, 4);
}

#[test]
fn push_incident_hands_the_mapped_message_to_the_transport() {
    let rec = Recorder { sent: RefCell::new(Vec::new()) };
    let cfg = NtfyConfig { base_url: "https://ntfy.example.lan".into(), topic: "home-alerts".into() };
    let inc = incident(Kind::DeauthFlood, Severity::High, 3, "deauth on 5180 MHz");
    push_incident(&rec, &cfg, &inc).expect("send");

    let sent = rec.sent.borrow();
    assert_eq!(sent.len(), 1);
    let (base, msg) = &sent[0];
    assert_eq!(base, "https://ntfy.example.lan");
    assert_eq!(msg.topic, "home-alerts");
    assert_eq!(msg.priority, 4);
    assert!(msg.body.contains("5180 MHz"));
}

#[test]
fn a_message_round_trips_as_json() {
    let inc = incident(Kind::RogueDhcp, Severity::High, 1, "rogue DHCP on VLAN8");
    let m = ntfy_message(&inc, "t");
    let json = serde_json::to_string(&m).expect("serialize");
    let back: NtfyMessage = serde_json::from_str(&json).expect("deserialize");
    assert_eq!(m, back);
}
